import os
import subprocess
import sys
import importlib
import base64
import stat
import socket

from typing import List


def error(*args):
    print(f"ERROR: {args}")


def os_system(cmd):
    return os.system(cmd)


def linux_do(cmd: str):
    if not cmd.endswith("> /dev/null"):
        cmd += "> /dev/null"
    os.system(cmd)


def linux_exec(cmd: str, ignore_error=False):
    code, result = subprocess.getstatusoutput(cmd)
    # print(cmd, result, code)
    if code and not ignore_error:
        raise Exception(f"linux_exec->{cmd}->{code}:{result}")
    return code, result


def unzip(name, user_name=""):
    zip_path = f"{name}.zip"
    if os.path.exists(zip_path):
        linux_do(f"rm -rf {name}")
        linux_do(f"unzip -o {zip_path} -d {name}")
    if user_name:
        linux_do(f"chown -R {user_name}:{user_name} {name}")


def append_sys_path(path):
    if path not in sys.path:
        sys.path.append(path)
    importlib.invalidate_caches()


_, ARCH = linux_exec("arch")
IGNORE_ARCH = "aarch64" if ARCH == "x86_64" else "x86_64"
PACKAGES_PATH = "/opt/cloud/site-packages"


def make_dir_if_not_exist(paths):
    root_path = ""
    for p in paths:
        root_path += p
        if root_path and not os.path.isdir(root_path):
            os.mkdir(root_path)
        root_path += "/"


def write_file(file_name, content, replace_flag=True):
    if os.path.exists(file_name):
        if not replace_flag:
            return
        os.remove(file_name)
    make_dir_if_not_exist(file_name.split("/")[:-1])
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    modes = stat.S_IWUSR | stat.S_IRUSR
    if isinstance(content, str):
        content = content.encode()
    with os.fdopen(os.open(file_name, flags, modes), "wb") as w_open:
        w_open.write(content)


def base64_encode(s):
    return base64.b64decode(s)


def get_host_ip():
    """
    查询本机ip地址
    :return: ip
    """
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        ip = s.getsockname()[0]
    finally:
        s.close()
        return ip


def mysql_exec(cmd, path, inout="<"):
    if "mysqldump" in cmd:
        inout = ">"
    if os.path.isfile(path):
        os.system(f"chown mysql:mysql {path}")
    if os.system(f'su mysql -c "{cmd} {inout} {path}"'):
        raise Exception(f"exec {path} fail")


def read_file(path):
    with open(path, "r", encoding="utf-8") as f:
        return f.read()
